// =============================================================
// CONFIG: Lightning Funded rules (April 2026, Tradeify 3.0)
// =============================================================
const ACCT = {
  "50K":  { start:50000, dd:2000, dll:1250, lockAt:52100, lockFloor:50100, goal1:3000, goalN:1500, cushion:500,  caps:[1500,2000,2500,3500], cost:295 },
  "100K": { start:100000, dd:3000, dll:2500, lockAt:103100, lockFloor:100100, goal1:6000, goalN:3000, cushion:1000, caps:[2000,3000,3500,5000], cost:575 },
  "150K": { start:150000, dd:5250, dll:3000, lockAt:155350, lockFloor:150100, goal1:9000, goalN:4500, cushion:1500, caps:[2500,3500,5000,7500], cost:750 },
};
const CONSISTENCY = [0.20, 0.25, 0.30, 0.30];
const SPLIT = 0.90;

// =============================================================
// SIMULATION CORE
// =============================================================
const dayMap = (() => {
  const m = new Map();
  for (const t of RAW_TRADES) {
    if (!m.has(t[0])) m.set(t[0], []);
    m.get(t[0]).push({ time: t[1], pnl: t[2], ae: t[3] });
  }
  return m;
})();
const DAY_LIST = Array.from(dayMap.keys()).sort();

function simulate(size, riskFn) {
  const cfg = ACCT[size];
  const accounts = []; const payouts = []; const blows = []; const softLocks = [];
  const equityCurve = [];
  let consBlocks = 0;

  const fresh = (date, idx) => ({
    idx, started: date, balance: cfg.start, floor: cfg.start - cfg.dd, locked: false,
    lastPayout: null, payoutsTaken: 0, cycleStart: cfg.start, cycleBest: 0, alive: true, ended: null,
  });

  let acct = fresh(DAY_LIST[0], 0);
  accounts.push(acct);

  for (const date of DAY_LIST) {
    if (!acct.alive) {
      acct = fresh(date, accounts.length);
      accounts.push(acct);
    }
    const trades = dayMap.get(date);
    let intraday = 0;
    let softed = false;
    for (const t of trades) {
      if (softed) continue;
      const buf = acct.balance - acct.floor;
      const r = riskFn(buf, acct.payoutsTaken, acct.locked);
      const m = r / 511;
      const sp = t.pnl * m;
      const sa = t.ae * m;
      const intraLow = intraday + sa;
      if (acct.balance + intraLow <= acct.floor) {
        blows.push({ date, acct: acct.idx, floor: acct.floor });
        acct.alive = false; acct.ended = date;
        // Final point of this account: at floor (where the account died)
        equityCurve.push({ d: date, b: acct.floor, f: acct.floor, a: acct.idx, ev: "blow", risk: r });
        // Null-break row — disconnects the line so next account doesn't connect via cliff/jump
        equityCurve.push({ d: date + "~brk" + acct.idx, b: null, f: null, a: acct.idx, brk: true });
        break;
      }
      if (intraLow <= -cfg.dll) {
        softLocks.push({ date, acct: acct.idx });
        softed = true; intraday = -cfg.dll; continue;
      }
      intraday += sp;
      if (intraday <= -cfg.dll) { softLocks.push({ date, acct: acct.idx }); softed = true; }
    }
    if (!acct.alive) continue;

    acct.balance += intraday;
    if (intraday > acct.cycleBest) acct.cycleBest = intraday;

    if (!acct.locked) {
      const nf = acct.balance - cfg.dd;
      if (nf > acct.floor) acct.floor = nf;
      if (acct.balance >= cfg.lockAt) { acct.floor = cfg.lockFloor; acct.locked = true; }
    }

    const cp = acct.balance - acct.cycleStart;
    const goal = acct.payoutsTaken === 0 ? cfg.goal1 : cfg.goalN;
    const cPct = CONSISTENCY[Math.min(acct.payoutsTaken, 3)];
    const cap = cfg.caps[Math.min(acct.payoutsTaken, 3)];

    let event = null, amt = null;
    if (cp >= goal) {
      if (acct.cycleBest <= cPct * cp + 0.01) {
        const maxTake = acct.balance - acct.floor - cfg.cushion;
        const a = Math.min(cap, maxTake, cp);
        if (a >= 1000) {
          payouts.push({ date, amount: a, acct: acct.idx, num: acct.payoutsTaken + 1 });
          acct.balance -= a; acct.lastPayout = date; acct.payoutsTaken += 1;
          acct.cycleStart = acct.balance; acct.cycleBest = 0;
          event = "payout"; amt = a;
        }
      } else { consBlocks += 1; }
    }
    equityCurve.push({ d: date, b: Math.round(acct.balance), f: Math.round(acct.floor), a: acct.idx, ev: event, amt, locked: acct.locked });
  }

  const totalPayout = payouts.reduce((s, p) => s + p.amount, 0);
  return {
    accounts: accounts.length, payouts: payouts.length, totalPayout,
    cash: totalPayout * SPLIT, costs: accounts.length * cfg.cost,
    net: totalPayout * SPLIT - accounts.length * cfg.cost,
    blows: blows.length, softLocks: softLocks.length, consBlocks,
    payoutList: payouts, blowList: blows, accountList: accounts.map(a => ({
      idx: a.idx, started: a.started, ended: a.ended, finalBal: a.balance, payouts: a.payoutsTaken,
    })),
    equityCurve,
  };
}

// =============================================================
// DERIVED ANALYTICS (run once on baseline)
// =============================================================
const dayPnls = DAY_LIST.map(d => ({
  date: d,
  pnl: dayMap.get(d).reduce((s, t) => s + t.pnl, 0),
}));

function dayOfWeekStats() {
  const dows = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
  const stats = {};
  dows.forEach(d => stats[d] = { name: d, count: 0, pnl: 0, wins: 0 });
  for (const { date, pnl } of dayPnls) {
    const dow = dows[new Date(date + "T12:00:00Z").getUTCDay()];
    stats[dow].count += 1;
    stats[dow].pnl += pnl;
    if (pnl > 0) stats[dow].wins += 1;
  }
  return ["Monday","Tuesday","Wednesday","Thursday","Friday"].map(d => ({
    ...stats[d],
    avg: stats[d].count ? stats[d].pnl / stats[d].count : 0,
    winRate: stats[d].count ? stats[d].wins / stats[d].count : 0,
  }));
}

function streakHist() {
  const streaks = [];
  let cur = 0;
  for (const { pnl } of dayPnls) {
    if (pnl < 0) cur += 1;
    else { if (cur > 0) streaks.push(cur); cur = 0; }
  }
  if (cur > 0) streaks.push(cur);
  const counts = {};
  for (const s of streaks) counts[s] = (counts[s] || 0) + 1;
  return Object.entries(counts).map(([k, v]) => ({ len: parseInt(k), count: v }))
    .sort((a, b) => a.len - b.len);
}

function monthlyPnl() {
  const m = {};
  for (const { date, pnl } of dayPnls) {
    const k = date.slice(0, 7);
    m[k] = (m[k] || 0) + pnl;
  }
  return Object.entries(m).map(([k, v]) => ({ month: k, pnl: v })).sort((a, b) => a.month.localeCompare(b.month));
}

const DOW_STATS = dayOfWeekStats();
const STREAK_HIST = streakHist();
const MONTHLY = monthlyPnl();

